sp_widget.client_script:
api.controller = function($rootScope) {
    var c = this;
    c.currentPage = c.data.currentPage || 1;
    c.filterStatus = c.data.filterStatus || '';
    c.filterSeverity = c.data.filterSeverity || '';
    c.filterSearch = c.data.filterSearch || '';
    c.filterUnassigned = c.data.filterUnassigned || false;

    // Listen to KPI card filter event
    $rootScope.$on('wei.filterTable', function(event, args) {
        if (args && args.filter) {
            if (args.filter.indexOf('status=') !== -1) {
                var m = args.filter.match(/status=([a-z_]+)/);
                if (m) c.filterStatus = m[1];
            } else if (args.filter.indexOf('severityIN') !== -1) {
                c.filterSeverity = 'critical';
            } else if (args.filter.indexOf('assigned_toISEMPTY') !== -1) {
                c.filterUnassigned = true;
            }
        } else {
            c.filterStatus = '';
            c.filterSeverity = '';
            c.filterUnassigned = false;
        }
        c.applyFilters();
    });

    c.applyFilters = function() {
        c.currentPage = 1;
        c.server.get({
            page: 1,
            filterStatus: c.filterStatus,
            filterSeverity: c.filterSeverity,
            filterSearch: c.filterSearch,
            filterUnassigned: c.filterUnassigned
        }).then(function(r) {
            c.data.records = r.data.records;
            c.data.totalPages = r.data.totalPages;
            c.data.totalRecords = r.data.totalRecords;
            c.data.pages = r.data.pages;
            c.currentPage = 1;
        });
    };

    c.resetFilters = function() {
        c.filterStatus = '';
        c.filterSeverity = '';
        c.filterSearch = '';
        c.filterUnassigned = false;
        c.applyFilters();
    };

    c.goToPage = function(page) {
        if (page < 1 || page > c.data.totalPages) return;
        c.currentPage = page;
        c.server.get({
            page: page,
            filterStatus: c.filterStatus,
            filterSeverity: c.filterSeverity,
            filterSearch: c.filterSearch,
            filterUnassigned: c.filterUnassigned
        }).then(function(r) {
            c.data.records = r.data.records;
            c.currentPage = r.data.currentPage;
        });
    };

    c.viewDetail = function(sysId) {
        var url = '?id=x_1956908_wareho_0_detail&record_id=' + sysId;
        window.location.href = url;
    };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:ital,wght@0,700;0,800;1,700&family=DM+Sans:wght@300;400;500;600;700&display=swap');

:root {
  --wei-bg:         #EEECEA;
  --wei-primary:    #5B4BF5;
  --wei-primary-dk: #4438D6;
  --wei-primary-lt: #EAE8FE;
  --wei-text:       #0F0F0F;
  --wei-muted:      #6B6B6B;
  --wei-border:     #D8D4D0;
  --wei-card:       #FFFFFF;
  --wei-radius:     12px;
  --wei-shadow:     0 2px 12px rgba(91,75,245,0.08);
  --wei-success:    #22C55E;
  --wei-warning:    #F59E0B;
  --wei-danger:     #EF4444;
  --wei-info:       #3B82F6;
  --ff-head:        'Playfair Display', Georgia, serif;
  --ff-body:        'DM Sans', -apple-system, BlinkMacSystemFont, sans-serif;
}

body, .sp-widget, .portal-page {
  font-family: var(--ff-body) !important;
  background-color: var(--wei-bg) !important;
  color: var(--wei-text) !important;
}

h1,h2,h3,h4,h5,h6 {
  font-family: var(--ff-head) !important;
}

.exc-table-header {
  background: #fff;
  border-bottom: 2px solid var(--wei-primary);
  padding: 16px 20px;
  border-radius: var(--wei-radius) var(--wei-radius) 0 0;
}
.exc-table-title {
  font-family: var(--ff-head) !important;
  font-size: 20px;
  font-weight: 800;
  color: var(--wei-text);
  margin: 0;
}

.filter-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 12px;
}
.filter-row .form-control {
  border-radius: 8px !important;
  border-color: var(--wei-border) !important;
  font-family: var(--ff-body) !important;
  font-size: 13px !important;
}
.filter-row .form-control:focus {
  border-color: var(--wei-primary) !important;
  box-shadow: 0 0 0 3px var(--wei-primary-lt) !important;
}
.btn-filter {
  background: var(--wei-primary) !important;
  color: #fff !important;
  border: none !important;
  border-radius: 8px !important;
  font-family: var(--ff-body) !important;
  font-weight: 600 !important;
  font-size: 12px !important;
  padding: 7px 16px !important;
}
.btn-filter-clear {
  background: transparent !important;
  color: var(--wei-muted) !important;
  border: 1px solid var(--wei-border) !important;
  border-radius: 8px !important;
  font-family: var(--ff-body) !important;
  font-size: 12px !important;
  padding: 7px 12px !important;
}

.table > thead > tr > th {
  background: #F8F7FE;
  font-family: var(--ff-body) !important;
  font-weight: 700;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--wei-primary);
  border-bottom: 2px solid var(--wei-primary-lt);
}
.table > tbody > tr > td {
  vertical-align: middle;
  font-size: 13px;
  font-family: var(--ff-body) !important;
  border-bottom: 1px solid #F0EEF8;
}
.table > tbody > tr:hover > td {
  background: #FAFAFE;
}

.exc-number-link {
  color: var(--wei-primary) !important;
  font-weight: 700;
  text-decoration: none !important;
}
.exc-number-link:hover { text-decoration: underline !important; }

.badge {
  border-radius: 6px !important;
  font-family: var(--ff-body) !important;
  font-weight: 700 !important;
  font-size: 10px !important;
  padding: 3px 8px !important;
  letter-spacing: 0.06em !important;
  text-transform: uppercase !important;
}
.badge-critical { background: var(--wei-danger) !important; color: #fff !important; }
.badge-high     { background: var(--wei-warning) !important; color: #fff !important; }
.badge-medium   { background: #FBBF24 !important; color: #000 !important; }
.badge-low      { background: var(--wei-success) !important; color: #fff !important; }
.badge-new      { background: var(--wei-primary) !important; color: #fff !important; }
.badge-assigned { background: var(--wei-info) !important; color: #fff !important; }
.badge-in_progress { background: var(--wei-warning) !important; color: #fff !important; }
.badge-resolved { background: var(--wei-success) !important; color: #fff !important; }
.badge-closed   { background: #6B7280 !important; color: #fff !important; }
.badge-pending  { background: #F97316 !important; color: #fff !important; }

.pagination > li > a,
.pagination > li > span {
  color: var(--wei-primary) !important;
  border-color: var(--wei-border) !important;
  font-family: var(--ff-body) !important;
  font-size: 13px !important;
}
.pagination > .active > a,
.pagination > .active > span {
  background: var(--wei-primary) !important;
  border-color: var(--wei-primary) !important;
  color: #fff !important;
}
.font-12 { font-size: 12px; font-family: var(--ff-body); }
.shadow-sm { box-shadow: var(--wei-shadow); }

sp_widget.script:
(function() {
    var tableName = 'x_1956908_wareho_0_exception';
    var userId = gs.getUserID();
    var pageSize = 10;
    var page = (input && input.page) ? parseInt(input.page, 10) : 1;
    if (page < 1) page = 1;

    data.records = [];
    data.title = options.title || 'Warehouse Exceptions';
    data.currentPage = page;
    data.totalPages = 1;
    data.totalRecords = 0;

    // Detect actual authenticated roles
    var isSupervisor = gs.hasRole('x_1956908_wareho_0.supervisor') || gs.hasRole('x_1956908_wareho_0.admin') || gs.hasRole('admin');
    var isTech = gs.hasRole('x_1956908_wareho_0.technician');
    var isStaff = !isSupervisor && !isTech;

    data.userRole = isSupervisor ? 'supervisor' : (isTech ? 'technician' : 'staff');

    // Strict server-side security: enforce queries based on role
    var baseQuery = '';
    if (isStaff) {
        // Staff can ONLY view their own reported exceptions
        baseQuery = 'reported_by=' + userId;
        data.title = data.title || 'My Reported Exceptions';
    } else if (isTech && !isSupervisor) {
        // Technician can ONLY view their assigned exceptions
        baseQuery = 'assigned_to=' + userId;
        data.title = data.title || 'My Assigned Exceptions';
    } else {
        // Supervisor view: default to all, or options.filter if provided by instance
        if (options.filter) {
            baseQuery = options.filter;
        }
        data.title = data.title || 'All Warehouse Exceptions';
    }

    // Dynamic filters from client
    var filterStatus = (input && input.filterStatus) || '';
    var filterSeverity = (input && input.filterSeverity) || '';
    var filterSearch = (input && input.filterSearch) || '';
    var filterUnassigned = (input && input.filterUnassigned) || false;

    data.filterStatus = filterStatus;
    data.filterSeverity = filterSeverity;
    data.filterSearch = filterSearch;
    data.filterUnassigned = filterUnassigned;

    var queryParts = [];
    if (baseQuery) queryParts.push(baseQuery);

    if (filterStatus) {
        queryParts.push('status=' + filterStatus);
    }
    if (filterSeverity) {
        queryParts.push('severity=' + filterSeverity);
    }
    if (filterUnassigned) {
        queryParts.push('assigned_toISEMPTY^statusNOT INresolved,closed');
    }
    if (filterSearch) {
        queryParts.push('numberLIKE' + filterSearch + '^ORshort_descriptionLIKE' + filterSearch + '^ORlocationLIKE' + filterSearch);
    }

    var finalQuery = queryParts.join('^');

    // Count records
    var countGr = new GlideAggregate(tableName);
    if (finalQuery) {
        countGr.addEncodedQuery(finalQuery);
    }
    countGr.addAggregate('COUNT');
    countGr.query();
    var total = 0;
    if (countGr.next()) {
        total = parseInt(countGr.getAggregate('COUNT'), 10) || 0;
    }
    data.totalPages = Math.max(1, Math.ceil(total / pageSize));
    data.totalRecords = total;

    if (page > data.totalPages) page = data.totalPages;
    data.currentPage = page;

    // Badges mapping
    var STATUS_CLASS = {
        'new': 'label-info',
        'assigned': 'label-warning',
        'in_progress': 'label-primary',
        'pending': 'label-warning',
        'resolved': 'label-success',
        'closed': 'label-default'
    };

    var PRIORITY_CLASS = {
        'p1_critical': 'label-danger',
        'p2_high': 'label-warning',
        'p3_medium': 'label-info',
        'p4_low': 'label-success'
    };

    var SEVERITY_CLASS = {
        'critical': 'label-danger',
        'high': 'label-warning',
        'medium': 'label-info',
        'low': 'label-success'
    };

    // Query records for page window
    var gr = new GlideRecord(tableName);
    if (finalQuery) {
        gr.addEncodedQuery(finalQuery);
    }
    gr.orderByDesc('sys_created_on');
    gr.chooseWindow((page - 1) * pageSize, page * pageSize);
    gr.query();

    while (gr.next()) {
        var sevVal = gr.getValue('severity') || 'medium';
        var priVal = gr.getValue('priority') || 'p3_medium';
        var stVal = gr.getValue('status') || 'new';

        data.records.push({
            sys_id: gr.getUniqueValue(),
            number: gr.getValue('number') || '',
            short_description: gr.getValue('short_description') || '',
            exception_type: gr.getDisplayValue('exception_type') || gr.getValue('exception_type') || '',
            location: gr.getValue('location') || 'General',
            severity: gr.getDisplayValue('severity') || sevVal,
            severityClass: SEVERITY_CLASS[sevVal] || 'label-default',
            priority: gr.getDisplayValue('priority') || priVal,
            priorityClass: PRIORITY_CLASS[priVal] || 'label-default',
            status: gr.getDisplayValue('status') || stVal,
            statusClass: STATUS_CLASS[stVal] || 'label-default',
            reported_by: gr.getDisplayValue('reported_by') || 'Staff',
            assigned_to: gr.getDisplayValue('assigned_to') || 'Unassigned',
            assignment_group: gr.getDisplayValue('assignment_group') || 'Operations',
            created: gr.getDisplayValue('sys_created_on') || '',
            updated: gr.getDisplayValue('sys_updated_on') || ''
        });
    }

    // Page numbers
    data.pages = [];
    for (var i = 1; i <= data.totalPages; i++) {
        data.pages.push(i);
    }
})();
